B(6,'Democracy','Democracy: ideas, forms and features','Who decides?',
 "In a class, who should decide the picnic spot: the teacher alone, a few students, or everyone together? How a group decides is the heart of government.",
 [("Democracy means rule by the people. The idea has evolved over time and has been practised in many societies.","democracy"),
  ("In direct democracy people take decisions themselves. In representative democracy people elect representatives to decide for them, as in India.","direct and representative"),
  ("Essential features include free and fair elections, equal rights, rule of law, freedom of expression and accountability of rulers.","features"),
  ("Democracy goes beyond government institutions. It also needs equality, respect and participation in everyday life.","beyond government"),
  ("India is a democratic republic with a written Constitution that guarantees fundamental rights.","India"),
  ("Different countries practise democracy differently, for example with a president or with a prime minister.","forms"),
  ("Democracy faces challenges such as inequality, misuse of power and low participation.","challenges"),
  ("Citizens strengthen democracy by voting, questioning and respecting others' rights.","citizens' role")],
 ("Classify: a village meeting where all adults vote on a well; Parliament passing laws.",[("A meeting where everyone votes is direct democracy.","People decide."),("Parliament is representative democracy.","Elected members decide."),("India uses mainly the representative form.","Large population.")]),
 ("What are the essential features of a democracy?",["Free and fair elections","Rights and rule of law","Accountability"],["Thinking democracy is only voting"]),
 ["Democracy is rule by the people.","Forms: direct and representative.","Key features include elections, rights and accountability.","Citizens must participate."],
 [mcq("ss6-1",1,"Democracy means rule by","the people",["one king","the army"],"By definition."),
  mcq("ss6-2",1,"India is a","representative democracy",["monarchy","direct democracy only"],"We elect representatives."),
  tf("ss6-3",1,"Democracy needs rights and rule of law.",True,"They are essential features."),
  mcq("ss6-4",2,"People deciding directly is","direct democracy",["dictatorship","oligarchy"],"No representatives."),
  mcq("ss6-5",2,"A challenge to democracy is","inequality",["literacy","sport"],"It weakens equal participation."),
  tf("ss6-6",2,"Democracy is only about elections.",False,"It also covers rights and participation."),
  short("ss6-7",3,"What document guarantees fundamental rights in India? (one word)",["constitution","the constitution"],"The Constitution."),
  mcq("ss6-8",3,"Accountability means leaders","answer to the people",["rule forever","avoid questions"],"They are answerable.")])
