  mcq("ss7-2",1,"Who conducts elections in India?","Election Commission",["Supreme Court","Army"],"An independent body."),
  tf("ss7-3",1,"In FPTP the candidate with most votes wins.",True,"Yes."),
  mcq("ss7-4",2,"A constituency elects","one member",["all members","no one"],"For Lok Sabha seats, one each."),
