  mcq("ss11-2",1,"A large region of similar climate and life is a","biome",["cell","delta"],"Forests, deserts, tundra."),
  tf("ss11-3",1,"Adaptation helps organisms survive in their habitat.",True,"Yes."),
  mcq("ss11-4",2,"A camel's wide feet help","walk on sand",["swim","climb trees"],"Do not sink."),
  mcq("ss11-5",2,"Biodiversity means","variety of life",["number of people","amount of rain"],"All living forms."),
